using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using UnityEditor;
using UnityEditor.SceneManagement;
using UnityEngine;
using Object=UnityEngine.Object;

namespace DiceCraft.Editor
{
    /// <summary>
    /// V1.1 (task W11, docs/specs/v11/PLAY_LAYOUT.md section 6): imports the default-theme surfaces of the new play screen
    /// from Assets/Art/Art11/Surfaces (generated by tools/art_v11/default/build_default11.py; W13 added the card template's
    /// rarity ring and gems) and appends them to
    /// GameApp.art07Templates in the Bootstrap scene, the list UiKit.Template resolves names from. Existing entries keep
    /// their order (the first entry with a name wins), so nothing that is already bound changes.
    /// Batch: Unity -batchmode -quit -projectPath DicePrototype -executeMethod DiceCraft.Editor.V11Setup.Integrate
    /// Afterwards run python tools/art_v11/theme_contract.py contract so the theme contract lists the new sprites.
    /// </summary>
    public static class V11Setup
    {
        public const string Root="Assets/Art/Art11";
        /// <summary>The UI surfaces (nine-slice sprites). Art11/Icons holds the compact card icons (W13), which are not
        /// templates and have their own import rule (V13IconImport).</summary>
        public const string SurfacesRoot=Root+"/Surfaces";
        // Mirrors BORDERS in tools/art_v11/default/build_default11.py: (left, bottom, right, top) in pixels.
        // W13 (CARD_TEMPLATE §6): the rarity ring is nine-sliced; the three gems are drawn whole (no border).
        private static readonly Dictionary<string,Vector4> Borders=new Dictionary<string,Vector4>(StringComparer.OrdinalIgnoreCase)
        {
            {"ui_dice_tray",new Vector4(72,72,72,72)},{"ui_topbar",new Vector4(40,40,40,40)},
            {"ui_chip_formula",new Vector4(40,40,40,40)},{"ui_stage_card",new Vector4(48,48,48,48)},
            {"ui_card_frame_rarity",new Vector4(40,40,40,40)},
            {"ui_gem_common",Vector4.zero},{"ui_gem_advanced",Vector4.zero},{"ui_gem_rare",Vector4.zero},
            {"ui_emblem_tier1",Vector4.zero},{"ui_emblem_tier2",Vector4.zero},
            {"ui_emblem_tier3",Vector4.zero},{"ui_emblem_tier4",Vector4.zero},
            {"ui_icon_stage",Vector4.zero},{"ui_icon_submit",Vector4.zero},{"ui_icon_interest",Vector4.zero}
        };

        public static void ConfigureImporter(string path,TextureImporter importer)
        {
            string name=Path.GetFileNameWithoutExtension(path);
            importer.textureType=TextureImporterType.Sprite;importer.spriteImportMode=SpriteImportMode.Single;
            importer.spritePixelsPerUnit=200;
            importer.spriteBorder=Borders.TryGetValue(name,out var border)?border:new Vector4(40,40,40,40);
            var settings=new TextureImporterSettings();importer.ReadTextureSettings(settings);
            settings.spriteMeshType=SpriteMeshType.FullRect;importer.SetTextureSettings(settings);
            importer.filterMode=FilterMode.Bilinear;importer.wrapMode=TextureWrapMode.Clamp;
            importer.mipmapEnabled=false;importer.alphaIsTransparency=true;importer.sRGBTexture=true;
            importer.alphaSource=TextureImporterAlphaSource.FromInput;
            importer.textureCompression=TextureImporterCompression.Uncompressed;importer.maxTextureSize=2048;importer.npotScale=TextureImporterNPOTScale.None;
            importer.SaveAndReimport();
        }

        [MenuItem("DiceCraft/V1.1/Integrate default play-screen surfaces (W11)")]
        public static void Integrate()
        {
            if(EditorApplication.isPlaying||EditorSceneManager.GetActiveScene().isDirty)
                throw new InvalidOperationException("Integration requires stopped play mode and a clean scene.");
            AssetDatabase.Refresh();
            string[] pngs=Directory.GetFiles(SurfacesRoot,"*.png",SearchOption.AllDirectories).Select(p=>p.Replace('\\','/')).OrderBy(p=>p,StringComparer.Ordinal).ToArray();
            if(pngs.Length==0)throw new InvalidOperationException("No PNG under "+SurfacesRoot+"; run tools/art_v11/default/build_default11.py first.");
            foreach(string path in pngs)ConfigureImporter(path,(TextureImporter)AssetImporter.GetAtPath(path));
            var sprites=pngs.Select(AssetDatabase.LoadAssetAtPath<Sprite>).Where(s=>s!=null).ToArray();
            if(sprites.Length!=pngs.Length)throw new InvalidOperationException($"Imported {sprites.Length} sprites from {pngs.Length} files.");

            var scene=EditorSceneManager.OpenScene("Assets/Game/Scenes/Bootstrap.unity");
            var app=Object.FindAnyObjectByType<GameApp>();if(app==null)throw new InvalidOperationException("Missing GameApp.");
            var families=new[]{"cards","constraint","economy","final","multiplier","seal","target"};
            app.defaultBossEmblems15=families.Select(family=>AssetDatabase.LoadAssetAtPath<Sprite>(
                V22iArtSetup.DefaultEmblemsRoot+"/emblem_"+family+".png")).ToArray();
            if(app.defaultBossEmblems15.Any(sprite=>sprite==null))
                throw new InvalidOperationException("The default style must bind all seven W15 boss emblems.");
            app.lootIllustrations15=Enumerable.Range(1,6).Select(n=>AssetDatabase.LoadAssetAtPath<Sprite>(
                "Assets/Art/Art11/Loot/illustration_L"+n+".png")).ToArray();
            var existing=app.art07Templates.Where(s=>s!=null).ToList();
            var known=new HashSet<string>(existing.Select(s=>s.name),StringComparer.OrdinalIgnoreCase);
            int added=0;
            foreach(var sprite in sprites)
            {
                // Same name already bound: replace that entry in place (a regenerated file keeps its slot); new names append.
                int at=existing.FindIndex(s=>string.Equals(s.name,sprite.name,StringComparison.OrdinalIgnoreCase));
                if(at>=0)existing[at]=sprite;else{existing.Add(sprite);added++;}
            }
            app.art07Templates=existing.ToArray();
            EditorUtility.SetDirty(app);EditorSceneManager.MarkSceneDirty(scene);EditorSceneManager.SaveScene(scene);AssetDatabase.SaveAssets();
            Debug.Log($"V11_W11_SURFACES_INTEGRATED sprites={sprites.Length} added={added} templates={app.art07Templates.Length}");
        }
    }
}
